insert into public.learnings (id, title, domain, level, format, source, hours, cpd, due, why, business_line, status, content) values
  ('L60', 'ITAA flash cards: corporate tax essentials', 'reg', 2, 'Flash cards', 'Tax & Legal academy', 1.5, 0, '', 'Six-minute daily reviews that keep rates and deadlines fresh before the ITAA exam.', null, 'published', '{"kind":"flash","total":24,"due":6,"next":"Thu 19 Nov","cards":[["Standard Belgian corporate income tax rate","25 %"],["Reduced rate for a qualifying SME, on its first €100,000 of profit","20 %"],["What is ITAA?","The Belgian professional body for tax advisers and accountants"],["Pillar Two minimum effective tax rate","15 %"],["What is the DBI/RDT regime?","The dividends-received deduction"],["Advance tax payments in a calendar financial year","Four instalments"]]}'::jsonb),
  ('L61', 'DP-700 practice exam', 'tec', 3, 'Practice exam', 'Microsoft Learn', 2, 0, '', 'Exam-style questions on ingesting, storing, transforming, securing and monitoring data in Microsoft Fabric.', null, 'published', '{"kind":"exam","bank":60,"real":"The real exam takes about 100 minutes; the pass mark is 700 of 1,000.","qs":[{"t":"Ingest","q":"You need to copy data from an on-premises SQL Server into a Fabric lakehouse every night. What do you use?","o":["A data pipeline with a Copy activity through an on-premises data gateway","A Power BI report with scheduled refresh","A KQL queryset","A Spark notebook without a gateway"],"a":0,"why":"Pipelines move data on a schedule, and the on-premises data gateway gives Fabric a route into the private network."},{"t":"Store","q":"Which table format do Fabric lakehouse tables use?","o":["CSV","Delta","Avro","JSON"],"a":1,"why":"Lakehouse tables are Delta tables: Parquet files plus a transaction log."},{"t":"Transform","q":"An analyst wants to clean data with Power Query, without writing code. Which item fits?","o":["Eventstream","Deployment pipeline","Dataflow Gen2","Activator"],"a":2,"why":"Dataflow Gen2 is the Power Query experience in Fabric."},{"t":"Secure","q":"Users may query a warehouse but must only see rows for their own region. What do you configure?","o":["A shortcut","Row-level security","A larger capacity","Workspace roles only"],"a":1,"why":"Row-level security filters rows per user; workspace roles control access to the item, not to rows."},{"t":"Monitor","q":"Where do you check run history and failures of pipelines across workspaces?","o":["The Monitoring hub","OneLake file explorer","The SQL analytics endpoint","The Power BI mobile app"],"a":0,"why":"The Monitoring hub lists runs, durations and failures across the items you can access."}]}'::jsonb),
  ('L62', 'ITAA mock exam: corporate income tax', 'reg', 3, 'Practice exam', 'Tax & Legal academy', 3, 2, '', '', null, 'published', '{"kind":"exam","bank":40,"real":"Questions follow the ITAA syllabus for corporate income tax.","qs":[{"t":"Rates","q":"What is the standard Belgian corporate income tax rate?","o":["20 %","25 %","29.58 %","33.99 %"],"a":1,"why":"The standard rate has been 25 % since assessment year 2021; 29.58 % and 33.99 % were earlier rates."},{"t":"SMEs","q":"On which part of its taxable profit does a qualifying SME pay the reduced rate?","o":["The first €100,000","The first €250,000","All of it","Only on dividends"],"a":0,"why":"The 20 % rate applies to the first €100,000; the rest is taxed at 25 %."},{"t":"Pillar Two","q":"Pillar Two applies to groups with consolidated revenue of at least…","o":["€750 million in two of the last four years","€50 million in the last year","€1 billion every year","€7.5 million in any year"],"a":0,"why":"The €750 million threshold, tested over two of the four preceding years, mirrors country-by-country reporting."},{"t":"Payments","q":"How many advance tax payment dates does a company with a calendar financial year have?","o":["Two","Three","Four","Twelve"],"a":2,"why":"There are four: in April, July, October and December."},{"t":"Profession","q":"What is ITAA?","o":["The federal tax administration","The Belgian professional body for tax advisers and accountants","An EU directive on interest","An accounting standard"],"a":1,"why":"ITAA regulates the professions of tax adviser and accountant in Belgium."}]}'::jsonb),
  ('L63', 'Fabric data engineering flash cards', 'tec', 2, 'Flash cards', 'Peer contribution', 1, 0, '', 'A deck a peer made while preparing DP-700, checked by two peers and a data expert.', null, 'published', '{"kind":"flash","total":18,"due":4,"next":"Fri 20 Nov","cards":[["What is OneLake?","The single, tenant-wide data lake that comes with Microsoft Fabric"],["Table format behind Fabric lakehouse tables","Delta (Parquet files with a transaction log)"],["What does a Dataflow Gen2 do?","Low-code ingestion and transformation with Power Query"],["Lakehouse or warehouse for a team that only writes T-SQL?","The warehouse"]]}'::jsonb),
  ('L64', 'Case: day-one operating model for a carve-out', 'tech', 3, 'Case exercise', 'Internal academy', 6, 0, '', '', null, 'published', '{"kind":"case","brief":"A Belgian retailer is carving out its online business into a separate company within nine months. The CFO wants a day-one operating model: which functions move, which stay with the parent under a transitional service agreement, and what that costs. All names are removed; the figures come from a real engagement.","deliv":["A one-page target operating model for day one","A list of transitional services with duration, owner and monthly cost","The five biggest day-one risks, each with a mitigation"],"rubric":["Structure and clarity","Realism of the transitional services","Quality of the risk thinking","Client-ready writing"],"reviewer":"Reviewed by your counsellor."}'::jsonb),
  ('L65', 'Teach-back: double materiality', 'reg', 3, 'Teach-back', 'AI tutor · CSRD bundle', 0.5, 0, '', '', null, 'published', '{"kind":"teach","prompt":"Explain double materiality to a CFO who has never heard of CSRD, in under 150 words.","crit":[["Impact materiality","impact|people|environment|society|planet"],["Financial materiality","financ|risk|cash|value|enterprise"],["Why both count","both|two|either|together|and also"],["Plain language",null]]}'::jsonb),
  ('L66', 'Stretch: prepare the steering committee', 'lead', 3, 'Stretch assignment', 'With your counsellor', 10, 0, '', 'Lead the preparation of one steering committee on your current engagement, with your counsellor as sponsor.', null, 'published', '{"kind":"stretch","brief":"Lead the preparation of one steering committee on your current engagement: agenda, decisions needed, pack and dry run. Your counsellor sponsors it and the engagement manager stays accountable for the meeting itself.","checks":["Agree scope and success criteria with your counsellor","Draft the agenda and the decisions needed","Build the pack and run the dry run with the engagement manager","Write a short reflection: what would you do differently?"]}'::jsonb),
  ('L67', 'Webinar: Pillar Two, one year of filings', 'reg', 3, 'Webinar', 'Tax & Legal academy', 1, 1, '', '', null, 'published', '{"kind":"webinar","mon":"DEC","day":"4","time":"12:30–13:30","when":"Fri 4 Dec 2026 · 12:30–13:30 CET · online","speakers":"With two Tax & Legal partners · questions open during the session","agenda":["What changed in the first year of Pillar Two filings","Common data gaps in the GloBE information return","Questions from the audience"]}'::jsonb),
  ('L68', 'Job aid: proposal pricing checklist', 'prof', 2, 'Job aid', 'Internal academy', 0.25, 0, '', '', null, 'published', '{"kind":"aid","items":["Scope written as outcomes, not activities","Assumptions and exclusions listed","Staffing pyramid matches the work","Fee compared with two similar past proposals","Risk premium agreed with the engagement partner","Payment terms and expenses stated"]}'::jsonb);
